 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Define cough and its purpose.",
   "back": "A rapid, short, deep inspiration with an open glottis, followed by a sudden, explosive, noisy expiration. It keeps the airways open by clearing secretions and particles. Non-specific, it accompanies almost any respiratory disease."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Describe the pathophysiology of cough.",
   "back": "An involuntary but controllable defence reflex. A productive cough should be respected; a useless dry irritative cough should be treated. Triggers: mechanical (smoke, dust, mucus), chemical (gastric acid in GERD) and thermal (cold air)."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Where are the tussigenic zones?",
   "back": "External ear canal, posterior pharynx, retrotonsillar space, inter-arytenoid larynx, trachea, carina and large bronchi (spurs especially), plus pleura, mediastinum, pericardium, diaphragm, oesophagus, stomach, and even the gallbladder, appendix and utero-adnexal regions."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Classify cough by duration and type.",
   "back": "Acute under 3 weeks, subacute 3 to 8 weeks, chronic over 8 weeks. Dry or productive. Permanent (sinus infection, cancer, whooping cough, fibrosis) or intermittent (allergy, GERD, bronchial hyperreactivity)."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Link cough timing and triggers to causes.",
   "back": "Nocturnal: GERD, asthma. Morning: bronchiectasis, chronic bronchitis. Postprandial: GERD. Position change: pleurisy, GERD. Supine: GERD, left heart failure. Exercise: asthma, heart failure. Cold, humidity, laughter, odours: asthma."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Name the special cough types.",
   "back": "Bitonal: recurrent nerve compression or paralysis. Painful: pleural or parietal involvement. Emetogenic (with vomiting): especially in children."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "List the causes of chronic cough.",
   "back": "Productive: chronic bronchitis, bronchiectasis, tuberculosis, bronchial cancer, asthma. Dry: bronchial cancer, interstitial lung disease, asthma, rhinitis or rhinosinusitis, GERD, ACE inhibitors, psychogenic."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Define sputum and bronchorrhoea.",
   "back": "Sputum: abnormal secretions from the subglottic airways coughed into the mouth. Excessive expectoration: over 30 mL/day. Bronchorrhoea: over 100 mL/day. Women and children often swallow sputum. Distinguish from nasal discharge."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Describe the mucociliary escalator.",
   "back": "Mucus traps inhaled particles and pathogens and coordinated cilia push it upward and out, protecting the lung. Irritation increases mucus, cleared by coughing. Clearance is reduced in bronchiectasis, chronic bronchitis, cystic fibrosis, primary ciliary dyskinesia and Kartagener syndrome, and in smokers."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "Name the sputum appearances.",
   "back": "Serous (transparent), mucous (colourless with grey gummy masses), purulent (frank pus), mucopurulent, frothy (white, aerated, sometimes pink), pearly (asthma, Laennec), haemoptoic (same value as hemoptysis)."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "Define vomica and its colours.",
   "back": "Sudden coughing up of an abundant purulent collection, often with nausea; massive over 100 mL, fractionated or nummular. Clear: hydatid cyst. Pus: abscess. Pus and bile: liver abscess with bronchial fistula. Chocolate: amoebic abscess."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "Hemoptysis versus haematemesis.",
   "back": "Hemoptysis: respiratory history, coughing, bright red, aerated, frothy blood. Haematemesis: digestive history, vomiting, dark non-aerated venous blood, sometimes with food."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "Grade hemoptysis and its signs.",
   "back": "Low under 50 mL; medium 300 to 500 mL; high over 500 mL at once or in 24 h. Same significance whatever the amount: an emergency. Severe: shock and respiratory distress. Moderate: malaise, laryngeal tingling, metallic taste, stable haemodynamics. Blood count falls."
  },
  {
   "id": "c13",
   "type": "text",
   "front": "List causes of hemoptysis.",
   "back": "Bronchopulmonary: cancer, tuberculosis, bronchiectasis, ruptured hydatid cyst, pneumonia, foreign body. Cardiovascular: valvulopathy, pulmonary oedema, embolism. Others: trauma, bleeding disorders. Idiopathic in 15 percent."
  },
  {
   "id": "c14",
   "type": "text",
   "front": "How is chest pain analysed?",
   "back": "Onset (sudden stabbing: pneumothorax; progressive: cancer), intensity, location and radiation, triggers (cough, position, breathing, palpation), associated signs, course, analgesic position and type (acute, chronic, phrenic neuralgia along the sternal edges)."
  },
  {
   "id": "c15",
   "type": "text",
   "front": "Give the acute causes of chest pain.",
   "back": "Acute coronary syndrome (retrosternal oppression radiating to arms or jaw), pulmonary embolism, aortic dissection (radiating to the back), oesophageal rupture (after vomiting), pneumothorax, pneumonia, pericarditis (relieved leaning forward), pleurisy, digestive and parietal causes, psychogenic (after excluding organic causes)."
  },
  {
   "id": "c16",
   "type": "text",
   "front": "Give the chronic causes of chest pain.",
   "back": "Cardiovascular: hypertrophic cardiomyopathy, tight aortic stenosis, pulmonary hypertension. Pleural: chronic pleurisy, mesothelioma. Mediastinal tumours. Digestive: GERD, pancreatitis, pancreatic or oesophageal cancer, gallstones (right shoulder). Parenchymal and parietal: cancer, metastases, spondylodiscitis."
  },
  {
   "id": "c17",
   "type": "text",
   "front": "Describe the mechanism and analysis of dyspnoea.",
   "back": "Breathing discomfort; normal rate about 16/min. It can come from any step: central control, the thoracic cage, airways, parenchyma, gas exchange or transport. Analyse onset (acute or chronic), intensity (NYHA, mMRC), type, timing, triggers and associated symptoms."
  },
  {
   "id": "c18",
   "type": "text",
   "front": "Name the types of dyspnoea.",
   "back": "Inspiratory: high obstruction. Expiratory: low obstruction (asthma). Orthopnoea: lying flat. Platypnoea: on sitting up. Apnoea, polypnoea, bradypnoea by rate. Paroxysmal nocturnal: heart failure. Postprandial: GERD, aspiration, food allergy."
  },
  {
   "id": "c19",
   "type": "text",
   "front": "List the causes of dyspnoea.",
   "back": "Acute: laryngotracheal (spasm, oedema, foreign body), bronchial (asthma), pulmonary (pneumonia, miliary), pleural (pleurisy, pneumothorax), cardiovascular (embolism, heart failure, pulmonary oedema). Chronic: COPD, asthma, bronchiectasis, tuberculosis, sarcoidosis, chronic pleurisy, recurrent embolism, left heart disease, mediastinal compression."
  }
 ],
 "deeper": [
  {
   "title": "Why ACE inhibitors cause a cough",
   "html": "<p>ACE also breaks down bradykinin. Blocking it lets bradykinin build up in the airways, where it sensitises the cough receptors, producing a persistent dry cough in a fair number of patients. Stopping the drug is the fix.</p><p class='src'>Source: the lecture's chronic dry cough causes, with standard pharmacology.</p>"
  },
  {
   "title": "Why every hemoptysis is treated as an emergency",
   "html": "<p>The danger in hemoptysis is less blood loss than drowning: blood flooding the airways blocks gas exchange. A small bleed can herald a large one, and the cause may be cancer or tuberculosis, which is why the lecture insists the amount does not change the significance.</p><p class='src'>Source: the lecture's hemoptysis slides.</p>"
  }
 ],
