 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Describe the pleural fluid effusion syndrome.",
   "back": "Fluid in the pleural cavity. Progressive onset with chest pain, dry cough and dyspnoea; fever depending on cause. Exam: reduced or abolished fremitus, dullness, reduced or absent breath sounds, sometimes a pleural rub. Complete general exam."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "What does the X-ray show in an effusion?",
   "back": "Homogeneous opacity with a meniscus-shaped margin and blunting of the costophrenic angle. Small: blunted sulcus only. Large: whole hemithorax opaque, mediastinal shift and tracheal deviation away."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Describe thoracentesis.",
   "back": "Sitting, with or without local anaesthesia, in the zone of complete dullness, shaving the upper edge of the lower rib. It confirms the effusion, shows its gross appearance (serofibrinous, purulent, haemorrhagic, chyliform) and provides samples."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Exudate versus transudate.",
   "back": "Exudate: albumin over 30 g/L, inflammatory origin. Transudate: albumin under 30 g/L, mechanical origin. Pleural biopsy and thoracoscopy confirm the cause."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Describe pneumothorax.",
   "back": "Air in the pleural cavity collapsing the lung. Spontaneous, traumatic or iatrogenic; primary (no lesion) or secondary (pre-existing disease). Air comes through a visceral pleural breach (ruptured emphysema bleb) or a parietal breach (chest wound)."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "What are the clinical signs of pneumothorax?",
   "back": "Sudden stabbing sub-mammary or subscapular pain, dyspnoea and dry cough. The hemithorax is distended and painful with reduced expansion, decreased fremitus, hyperresonance and reduced or absent breath sounds."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "What does imaging show in pneumothorax?",
   "back": "A hyperlucent area devoid of bronchovascular markings, bounded by a thin visceral pleural line around the collapsed lung. Effects on neighbours: contralateral mediastinal shift, depressed hemidiaphragm, widened intercostal spaces. Treated by needle aspiration."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Describe the mixed effusion syndrome.",
   "back": "Air and fluid together: pneumothorax symptoms, with fluid signs at the base topped by air signs; on X-ray an opacity surmounted by lucency. Fluid: yellow (hydro-), pus (pyo-), blood (haemo-) or chyle (chylo-pneumothorax)."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Describe the lung consolidation syndrome.",
   "back": "A lobe or segment no longer ventilates, often filled with alveolar exudate. Increased fremitus, dullness, bronchial breath sounds, crackles. X-ray: dense homogeneous confluent opacity with indistinct borders, air bronchogram, systematised to a lobe or segment."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "Retracted versus non-retracted consolidation.",
   "back": "Non-retracted: acute pneumonia, pulmonary infarction, tuberculous pneumonia. Retracted: intrinsic or extrinsic bronchial stenosis, parenchymal destruction; structures shift toward the affected side with rib crowding."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "Describe the emphysema syndrome.",
   "back": "Damaged alveoli distend into large air spaces; centrilobular (blue bloater) or panlobular (pink puffer). Cough, worsening dyspnoea, barrel chest, polypnoea, diffuse hyperresonance, decreased fremitus and breath sounds. X-ray: increased AP diameter and retrosternal space."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "Describe the cavitary syndrome.",
   "back": "Loss of lung substance from a tuberculous cavern, lung abscess, excavated cancer or ruptured hydatid cyst. Fever, cough, expectoration, vomica; dullness, increased fremitus, subcrackles; an excavated image on X-ray."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "Describe the bronchial syndromes.",
   "back": "Acute bronchitis: mucosal inflammation, dry then productive cough, often normal exam and X-ray. Chronic bronchitis: cough and sputum 3 months a year for 2 years; barrel chest, clubbing, cyanosis. Bronchiectasis: permanent dilatation of 3rd to 8th order bronchi, morning bronchorrhoea, clubbing, rhonchi; CT and bronchoscopy."
  },
  {
   "id": "c13",
   "type": "text",
   "front": "What is a mediastinal syndrome?",
   "back": "Clinical and radiological signs from irritation or compression of mediastinal organs: respiratory (dyspnoea, dry cough, rare hemoptysis), circulatory, neurological and digestive."
  },
  {
   "id": "c14",
   "type": "text",
   "front": "Describe superior vena cava syndrome.",
   "back": "Obstruction of SVC flow, mostly thrombus or tumour. Early: dizziness, tinnitus, headache, eyelid oedema, jugular turgor. Late: oedema of face, neck and thorax, collateral veins, telangiectasia, cyanosis worse on coughing. Without an opacity, think SVC thrombosis (Behçet) or fibrous mediastinitis. IVC syndrome (rarer): hepatomegaly, ascites, leg oedema."
  },
  {
   "id": "c15",
   "type": "text",
   "front": "Name the neurological and digestive mediastinal signs.",
   "back": "Sympathetic: Horner syndrome; with apex tumour and bone lysis, Pancoast-Tobias syndrome. Phrenic: hiccups, girdle neuralgia, diaphragmatic paralysis. Recurrent: dysphonia or aphonia. Vagus: dyspnoea, bradycardia, sialorrhoea. Oesophageal compression: dysphagia, posterior opacity (neurinoma)."
  }
 ],
 "deeper": [
  {
   "title": "Why the trachea tells you effusion from collapse",
   "html": "<p>A large effusion adds volume to one side and pushes the mediastinum and trachea away. A retracted consolidation from a blocked bronchus removes volume and pulls them toward it. Both look white on the X-ray, so the position of the trachea is the quickest clue to which one you face.</p><p class='src'>Source: the lecture's effusion and retracted consolidation slides.</p>"
  },
  {
   "title": "Why the needle goes above the rib",
   "html": "<p>The intercostal vein, artery and nerve run along the lower border of each rib. Inserting the needle just above the lower rib keeps it away from that bundle, avoiding bleeding and nerve injury during thoracentesis.</p><p class='src'>Source: the lecture's thoracentesis technique slide.</p>"
  }
 ],
