 "sourceFile": "adrenal semiology 2025.pptx (Endocrinology semiology, Pr. Ioana Hristov, 2025-2026)",
 "sourceUrl": "https://drive.google.com/file/d/1nl01u98kwMmqaF9rlpmM8dYVSnl4-K73/view?usp=drivesdk",
 "buildNote": "<strong>Partial page.</strong> Most slides in this 28 MB PowerPoint are images, so only the readable text is covered: Cushing's syndrome, its ACTH-based classification, and adrenal and catecholamine imaging. A PDF export of the slides would let this page be completed. If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>The adrenal lecture centres on <strong>cortisol excess</strong>: recognise the Cushingoid picture, then use <strong>ACTH</strong> to find the source, and imaging to locate it.</p>"
  },
  {
   "id": "s1",
   "title": "The clinical picture of hypercortisolism",
   "html": "<p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>System</th><th scope='col'>Signs</th></tr></thead><tbody><tr><th scope='row'>Fat</th><td>Truncal obesity, moon face</td></tr><tr><th scope='row'>Skin</th><td>Purple striae, acne</td></tr><tr><th scope='row'>Muscle</th><td>Limb atrophy</td></tr><tr><th scope='row'>Metabolic</th><td>Diabetes or prediabetes, hypertension</td></tr><tr><th scope='row'>Bone</th><td>Osteoporosis</td></tr><tr><th scope='row'>Blood</th><td>High thrombosis risk</td></tr><tr><th scope='row'>Mind</th><td>Depression and suicide risk, or euphoria</td></tr><tr><th scope='row'>Sex</th><td>Hirsutism and cycle troubles; erectile dysfunction</td></tr></tbody></table></div></p>"
  },
  {
   "id": "s2",
   "title": "Finding the source",
   "html": "<p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>ACTH</th><th scope='col'>Source</th></tr></thead><tbody><tr><th scope='row'>High (ACTH-dependent)</th><td>Pituitary (Cushing's disease) or ectopic</td></tr><tr><th scope='row'>Low (ACTH-independent)</th><td>Adrenal</td></tr></tbody></table></div></p><p><strong>Adrenal CT</strong> shows size, lipid structure and extension of an adenoma. <strong>MIBG scintigraphy</strong> evaluates catecholamine-secreting tissue, including paragangliomas.</p>"
  }
 ],
