   "type": "text",
   "front": "How is severity assessed?",
   "back": "Warning: pallor, cold extremities, restlessness, tachycardia. Severe: hypotension, polypnoea, oliguria, altered consciousness, mottling. Haemoglobin falls, but a normal value does not rule out recent bleeding. Haematemesis with melena or rectal bleeding means abundant bleeding."
